// Waypoint — full airport coordinate lookup.
//
// A large background lookup table — NOT a visible suggestion list (that
// stays airports.js/COMMON_AIRPORTS, a small curated shortlist of major
// hubs) — used purely to resolve a real, precise coordinate for a
// Flight leg's "From"/"To" airport code at save time, for any airport
// with an IATA code, not just the ~126 major hubs COMMON_AIRPORTS
// covers. See airportCoordsForCode() in index.html: it checks
// COMMON_AIRPORTS first (for the busiest hubs, where a hand-curated
// display name is worth having), then falls back to this file for
// everything else. This is what lets a leg between two SECONDARY
// airports — not just the big hubs — resolve on the Map tab without
// ever touching Nominatim's free-text geocoding.
//
// Data source: the `airportsdata` Python package (PyPI), which bundles
// a comprehensive, actively-maintained database built from OurAirports
// (https://ourairports.com — the standard free/public-domain airport
// dataset). The original ask was to pull OpenFlights' airports.dat
// specifically, but that file (~7,700 rows) couldn't be fetched in
// full through this app's web-fetching tools — they summarize/truncate
// large raw files rather than returning them verbatim, so what came
// back was silently missing >90% of the rows. airportsdata's dataset
// serves the same purpose (comprehensive, IATA-coded, lat/lon per
// airport) and is more current, so it was used instead of a truncated,
// wrong OpenFlights pull — flagging that substitution here since it
// wasn't the exact source originally asked for.
//
// Format: { "CODE": [name, city, countryCode, lat, lng], ... } — a
// compact array per entry (rather than a named-property object) purely
// to keep this file's size down; it's ~550KB across 7,884 airports.
// countryCode is the ISO 3166-1 alpha-2 code (e.g. "GB", "US"), not a
// full country name — this file is a coordinate/lookup source, not a
// display source, so spelling out full country names for nearly 8,000
// rarely-shown entries wasn't worth the extra size. A future UI change
// that wants to actually SHOW entries from this file (rather than just
// use it for coordinate math) would want to map that code to a full
// name at render time, not bake it in here.
//
// Loaded with `defer` (see the <script> tag near the top of
// index.html, unlike the other data/*.js files) since — unlike
// COMMON_CURRENCIES/COMMON_AIRPORTS/etc., which the very first form a
// viewer opens needs for its <datalist> suggestions — this file is
// only ever touched later, when a Flight leg is actually saved. Not
// blocking on it during initial page parse keeps first load faster,
// with no behavioural difference: it's guaranteed to have finished
// loading by the time any interaction could possibly need it.
